/// <summary>
///     The <c>AVAInventMovementCls_Extension</c> class is the extension for <c>InventTable</c>
/// </summary>
[ExtensionOf(classStr(InventMovement))]
final class AVAInventMovementCls_Extension
{


}

Method.Source:
/// <summary>
///     Changes the quantity to an acceptable value using the specified conflicts resolution strategy if the quantity constraints are violated.
/// </summary>
/// <param name = "_buffer">
///     The record that serves as the inventory movement originator.
/// </param>
/// <param name = "_errorCorrectionMethods">
///     The error correction methods.
/// </param>
/// <param name = "_useDefaultOrderSetup">
///     A Boolean value indicating whether the constraints should be derived
///     from the default (cross-site) order settings regardless of the inventory dimensions of the record.
/// </param>
public static void ensureTransQtyIsAcceptableForBuffer( Common                                          _buffer,
                                                        InventMovementQuantityErrorCorrectionMethods    _errorCorrectionMethods,
                                                        boolean                                         _useDefaultOrderSetup   )
{
    SalesLine   locSalesLine;
    SalesQty    locSalesQty;
    str         locBoxInfoTxt;

    if(_buffer.TableId == tableNum(SalesLine))
    {
        locSalesLine    = _buffer;
        locSalesQty     = locSalesLine.SalesQty;
    }

    next ensureTransQtyIsAcceptableForBuffer(   _buffer,
                                                _errorCorrectionMethods,
                                                _useDefaultOrderSetup   );

    if(     locSalesLine.AVAItemSet             != NoYes::Yes 
        &&  locSalesLine.AVAItemSetComponent    != NoYes::Yes   )
    {
        if(     locSalesLine.SalesQty   > locSalesQty
            &&  locSalesLine.SalesQty   != 0            )
        {
            //locBoxInfoTxt = strFmt("%1: ", locSalesLine.SalesId);
            //locBoxInfoTxt += strFmt("%1 %2: ", "@NDX:NXAPosDot", locSalesLine.LineNum); // no LinNum available
            locBoxInfoTxt += strFmt("@NDX:NXAItemP1QuantityIncreasedFromP2ToNextPossibleP3", locSalesLine.ItemId, locSalesQty, locSalesLine.SalesQty);
            Box::info(locBoxInfoTxt);
        }
    }
}

/// <summary>
/// Changing ModuleType for InventTransferLine so that qty check quantities get taken from sales block
/// </summary>
/// <returns>ModuleInventPurchSales</returns>
protected ModuleInventPurchSales moduleType()
{
    ModuleInventPurchSales locModuleType = next ModuleType();

    if(buffer.TableId == tableNum(InventTransferLine)
        && subType == InventMovSubType::None)
    {
        locModuleType = ModuleInventPurchSales::Sales;
    }

    return locModuleType;
}
